import xml.etree.ElementTree as ET

tree = ET.parse('/work/output/artifacts/skill-bpmn-event-trigger-start/InboxTriggerBpmn/InboxTriggerBpmn.bpmn')
root = tree.getroot()

ns = {
    'bpmn': 'http://www.omg.org/spec/BPMN/20100524/MODEL',
    'bpmndi': 'http://www.omg.org/spec/BPMN/20100524/DI',
    'uipath': 'http://uipath.org/schema/bpmn',
}

issues = []

# 1. root namespace check
assert 'http://www.omg.org/spec/BPMN/20100524/MODEL' in root.tag or root.tag.endswith('}definitions'), "bad root"

# Collect all ids
all_ids = {e.get('id') for e in root.iter() if e.get('id')}

# 2. shapes and edges
diagram = root.find('bpmndi:BPMNDiagram', ns)
shapes = {s.get('bpmnElement') for s in diagram.findall('.//{http://www.omg.org/spec/BPMN/20100524/DI}BPMNShape')}
edges  = {e.get('bpmnElement') for e in diagram.findall('.//{http://www.omg.org/spec/BPMN/20100524/DI}BPMNEdge')}

proc = root.find('bpmn:process', ns)
flow_nodes = [c for c in proc if not c.tag.endswith('}sequenceFlow') and not c.tag.endswith('}extensionElements')]
seq_flows  = [c for c in proc if c.tag.endswith('}sequenceFlow')]

node_ids = {n.get('id') for n in flow_nodes}
flow_ids = {f.get('id') for f in seq_flows}

missing_shapes = node_ids - shapes
missing_edges  = flow_ids - edges

if missing_shapes: issues.append(f'Missing shapes: {missing_shapes}')
if missing_edges:  issues.append(f'Missing edges: {missing_edges}')

# 3. ref resolution
for f in seq_flows:
    for attr in ('sourceRef', 'targetRef'):
        v = f.get(attr)
        if v not in all_ids:
            issues.append(f'Flow {f.get("id")} {attr}={v} not found')

# 4. start events – must have outgoing, no incoming
for se in proc.findall('bpmn:startEvent', ns):
    incoming = se.findall('bpmn:incoming', ns)
    if incoming: issues.append(f'StartEvent {se.get("id")} has incoming (should have none)')
    # must carry event extension
    ev_ext = se.find('.//uipath:event', ns)
    print(f'StartEvent {se.get("id")}: uipath:event present={ev_ext is not None}')
    med = se.find('bpmn:messageEventDefinition', ns)
    print(f'StartEvent {se.get("id")}: messageEventDefinition present={med is not None}')
    ev_type = se.find('.//uipath:type', ns)
    if ev_type is not None:
        print(f'  uipath:type value={ev_type.get("value")}')

# 5. No manual (bare) start event
for se in proc.findall('bpmn:startEvent', ns):
    has_def = se.find('bpmn:messageEventDefinition', ns) is not None or \
              se.find('bpmn:timerEventDefinition', ns) is not None
    has_uipath_ev = se.find('.//uipath:event', ns) is not None
    if not has_def and not has_uipath_ev:
        issues.append(f'Bare/manual start event found: {se.get("id")}')

print('Issues:', issues if issues else 'none')
print('STRUCTURAL CHECK: PASSED' if not issues else 'STRUCTURAL CHECK: FAILED')
